import { useMemo, useState } from 'react';
import {
  useReactTable,
  getCoreRowModel,
  PaginationState,
} from '@tanstack/react-table';
import usePageQuery from '../../core/hooks/usePageQuery';
import { useGetAllInventoryQuery, useGetUserQuery } from '../posApi';
import useInventoryDetailsColumn from './useInventoryDetailsColumn';
import { IUserInfo } from '../../core/Interface/user.interface';
import {
  IInventoryDetails,
  IInventoryDetailsData,
} from '../../core/Interface/inventory.interface';
import React from 'react';

// rows that comfortably fit the viewport (hero ~90px + search ~52px + pagination ~52px + chrome ~112px)
const calcPageSize = () => {
  const available = window.innerHeight - 306;
  return Math.max(5, Math.floor((available - 48) / 52));
};

const useInventoryDetails = (
  handleOpenStockAdjust: (product: IInventoryDetailsData) => void
) => {
  const { page } = usePageQuery();
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: page,
    pageSize: calcPageSize(),
  });

  // Recalculate page size on window resize
  React.useEffect(() => {
    const handleResize = () => {
      setPagination((prev) => ({ ...prev, pageSize: calcPageSize() }));
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);
  const [searchText, setSearchText] = useState('');
  const { data: companyData } = useGetUserQuery();

  const currencyCode = useMemo(() => {
    if (companyData?.data) {
      const userData = companyData.data as IUserInfo;
      if (userData.company.currencyCode) {
        return userData.company.currencyCode;
      }
    }
    return '';
  }, [companyData]);

  const {
    data: InventoryDetailsData,
    isLoading,
    isFetching,
    error,
  } = useGetAllInventoryQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText,
  });

  const InventoryDetailsMemo = useMemo(() => {
    return InventoryDetailsData?.data as IInventoryDetails;
  }, [InventoryDetailsData?.data]);

  const filteredData = useMemo(() => {
    if (!InventoryDetailsMemo?.records) return [];

    const text = searchText.toLowerCase().trim();

    return InventoryDetailsMemo.records.filter((record) => {
      const code = record.code?.toLowerCase() ?? '';
      const name = record.name?.toLowerCase() ?? '';

      return name.includes(text) || code.includes(text);
    });
  }, [InventoryDetailsMemo, searchText]);

  const columns = useInventoryDetailsColumn(
    currencyCode,
    handleOpenStockAdjust
  );

  const table = useReactTable({
    data: error ? [] : filteredData ?? [],
    columns,
    state: { pagination },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
    initialState: { columnVisibility: { id: false } },
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error,
    totalCount: InventoryDetailsMemo?.totalRecords ?? 0,
    searchText,
    setSearchText,
  };
};

export default useInventoryDetails;
